struct zinterrupt_set {
  enum kind_zinterrupt_set kind;
  union {
    struct { uint64_t zInts_Delegated; };
    struct { unit zInts_Empty; };
    struct { uint64_t zInts_Pending; };
  } variants;
};

static void CREATE(zinterrupt_set)(struct zinterrupt_set *op) {
  op->kind = Kind_zInts_Delegated;
}

static void RECREATE(zinterrupt_set)(struct zinterrupt_set *op) {

}

