// union exception
enum kind_zexception { Kind_zError_internal_error, Kind_zError_not_implemented };

struct zexception {
  enum kind_zexception kind;
  union {
    struct { unit zError_internal_error; };
    struct { sail_string zError_not_implemented; };
  } variants;
};

static void CREATE(zexception)(struct zexception *op) {
  op->kind = Kind_zError_internal_error;
}

static void RECREATE(zexception)(struct zexception *op) {

}

static void KILL(zexception)(struct zexception *op) {
  if (op->kind == Kind_zError_not_implemented) {
    KILL(sail_string)(&op->variants.zError_not_implemented);
  }
}

static void COPY(zexception)(struct zexception *rop, struct zexception op) {
  if (rop->kind == Kind_zError_not_implemented) {
    KILL(sail_string)(&rop->variants.zError_not_implemented);
  };
  rop->kind = op.kind;
  if (op.kind == Kind_zError_internal_error) {
    rop->variants.zError_internal_error = op.variants.zError_internal_error;
  } else if (op.kind == Kind_zError_not_implemented) {
    CREATE(sail_string)(&rop->variants.zError_not_implemented); COPY(sail_string)(&rop->variants.zError_not_implemented, op.variants.zError_not_implemented);
  }
}

static bool EQUAL(zexception)(struct zexception op1, struct zexception op2) {
  if (op1.kind == Kind_zError_internal_error && op2.kind == Kind_zError_internal_error) {
    return EQUAL(unit)(op1.variants.zError_internal_error, op2.variants.zError_internal_error);
  } else if (op1.kind == Kind_zError_not_implemented && op2.kind == Kind_zError_not_implemented) {
    return EQUAL(sail_string)(op1.variants.zError_not_implemented, op2.variants.zError_not_implemented);
  } else return false;
}

static void zError_internal_error(struct zexception *rop, unit op) {
  if (rop->kind == Kind_zError_not_implemented) {
    KILL(sail_string)(&rop->variants.zError_not_implemented);
  }
  rop->kind = Kind_zError_internal_error;
  rop->variants.zError_internal_error = op;
}

static void zError_not_implemented(struct zexception *rop, const_sail_string op) {
  if (rop->kind == Kind_zError_not_implemented) {
    KILL(sail_string)(&rop->variants.zError_not_implemented);
  }
  rop->kind = Kind_zError_not_implemented;
  CREATE(sail_string)(&rop->variants.zError_not_implemented);
  COPY(sail_string)(&rop->variants.zError_not_implemented, op);
}

